#M+KV{{75X0q+L+K|YpW|Nfu<1G~=)lm')))
root=Path.cwd()
for row in ROWS:
    p=root/row['path']
    assert p.resolve().is_relative_to(root.resolve()), 'Chemin invalide'
    actual=hashlib.sha256(p.read_bytes()).hexdigest() if p.exists() else None
    if actual not in (row['before'],row['after']):
        raise RuntimeError('Modification concurrente : '+row['path'])
    raw=base64.b64decode(row['content'])
    assert hashlib.sha256(raw).hexdigest()==row['after'], 'Contenu corrompu'
for row in ROWS:
    p=root/row['path']; p.parent.mkdir(parents=True,exist_ok=True)
    tmp=p.with_name(p.name+'.media-tmp')
    tmp.write_bytes(base64.b64decode(row['content']))
    os.replace(tmp,p)
print(str(len(ROWS))+' fichiers publiables appliqués, fiches et CRM conservés.')
